using System.Collections.Generic;
using UnityEngine;

namespace Farm
{
    /// <summary>All game sprites by name. Generated by menu Farm/Setup Project.</summary>
    public class SpriteDB : ScriptableObject
    {
        public const string ResourcePath = "FarmSpriteDB";
        public List<Sprite> sprites = new List<Sprite>();
        /// <summary>Hash of sprite_layout.json used to build this DB (editor re-imports when it changes).</summary>
        public string layoutHash;

        [System.NonSerialized] private Dictionary<string, Sprite> map;
        private static SpriteDB instance;

        public static SpriteDB Instance
        {
            get
            {
                if (instance == null) instance = Resources.Load<SpriteDB>(ResourcePath);
                return instance;
            }
        }

        /// <summary>True when the atlas really contains this sprite (no fallback, no warning).</summary>
        public static bool Exists(string name)
        {
            SpriteDB db = Instance;
            if (db == null || string.IsNullOrEmpty(name)) return false;
            if (db.map == null)
            {
                db.map = new Dictionary<string, Sprite>();
                foreach (Sprite sp in db.sprites)
                    if (sp != null) db.map[sp.name] = sp;
            }
            return db.map.TryGetValue(name, out Sprite s) && s != null && s.name == name;
        }

        public static Sprite Get(string name)
        {
            SpriteDB db = Instance;
            if (db == null || string.IsNullOrEmpty(name)) return null;
            if (db.map == null)
            {
                db.map = new Dictionary<string, Sprite>();
                foreach (Sprite s in db.sprites)
                    if (s != null) db.map[s.name] = s;
            }
            if (db.map.TryGetValue(name, out Sprite sp)) return sp;
            // Art not generated yet: use the placeholder so the game stays playable.
            if (Defs.SpriteFallbacks.TryGetValue(name, out string fb) && db.map.TryGetValue(fb, out sp))
            {
                db.map[name] = sp;
                return sp;
            }
            Debug.LogWarning("[Farm] Sprite not found: " + name);
            db.map[name] = null;
            return null;
        }
    }
}
